1	// Package openaicompat contains shared OpenAI-compatible Chat Completions
2	// protocol plumbing. Provider identity, cost attribution, routing, and
3	// provider-specific discovery live in provider packages above this layer.
4	package openaicompat
5	
6	import (
7		"context"
8		"encoding/json"
9		"net/http"
10		"time"
11	
12		agent "github.com/easel/fizeau/internal/core"
13		"github.com/easel/fizeau/internal/provider/quotaheaders"
14		oai "github.com/openai/openai-go"
15		"github.com/openai/openai-go/option"
16		"github.com/openai/openai-go/packages/param"
17	)
