19	// Config contains the protocol/client settings shared by providers that speak
20	// the OpenAI-compatible Chat Completions API.
21	type Config struct {
22		BaseURL string
23		APIKey  string
24		Headers map[string]string
25		// QuotaHeaderParser, when set, is called on every response to convert
26		// the response Header into a quotaheaders.Signal. The signal is then
27		// forwarded to QuotaSignalObserver. Different providers (OpenAI vs
28		// OpenRouter) use different parsers, so the protocol layer takes the
29		// parser as a function and stays provider-agnostic.
30		QuotaHeaderParser func(http.Header, time.Time) quotaheaders.Signal
31		// QuotaSignalObserver, when set together with QuotaHeaderParser, receives
32		// the parsed signal on every response. The service layer wires this to
33		// the provider quota state machine.
34		QuotaSignalObserver func(quotaheaders.Signal)
35	}
36	
37	// Client wraps openai-go with agent-native request and response conversion.
38	type Client struct {
39		client *oai.Client
40	}
41	
42	// NewClient creates an OpenAI-compatible protocol client.
43	func NewClient(cfg Config) *Client {
44		opts := []option.RequestOption{
45			option.WithBaseURL(cfg.BaseURL),
46			option.WithMaxRetries(0),
47		}
48		if cfg.APIKey != "" {
49			opts = append(opts, option.WithAPIKey(cfg.APIKey))
50		} else {
51			opts = append(opts, option.WithAPIKey("not-needed"))
52		}
53		for k, v := range cfg.Headers {
54			opts = append(opts, option.WithHeader(k, v))
55		}
56		// SSE comment-frame filter must sit before the debug sink so the sink
57		// observes the same byte stream the decoder will see. Middlewares are
58		// applied in registration order, outermost first.
59		opts = append(opts, option.WithMiddleware(SSEFilterMiddleware()))
60		if s := ResolveDebugSink(); s != nil {
61			opts = append(opts, option.WithMiddleware(DebugMiddleware(s)))
62		}
63		if cfg.QuotaHeaderParser != nil && cfg.QuotaSignalObserver != nil {
64			opts = append(opts, option.WithMiddleware(quotaHeaderMiddleware(cfg.QuotaHeaderParser, cfg.QuotaSignalObserver)))
65		}
66	
67		client := oai.NewClient(opts...)
68		return &Client{client: &client}
69	}
70	
71	// quotaHeaderMiddleware returns a middleware that runs `parser` on every
72	// response Header and forwards the resulting Signal to `observer`. The
73	// middleware is a no-op when the upstream call returns an error before a
74	// Response is produced, and runs *after* the response has been received but
75	// *before* the SDK consumes its body — both branches still surface the same
76	// (resp, err) tuple to the caller.
77	func quotaHeaderMiddleware(parser func(http.Header, time.Time) quotaheaders.Signal, observer func(quotaheaders.Signal)) option.Middleware {
78		return func(req *http.Request, next option.MiddlewareNext) (*http.Response, error) {
79			resp, err := next(req)
80			if resp != nil {
81				signal := parser(resp.Header, time.Now())
82				if signal.Present {
83					observer(signal)
84				}
85			}
86			return resp, err
87		}
88	}
