90	// RequestOptions are request controls that map directly to the compatible Chat
91	// Completions wire shape. ExtraOptions carries provider-owned extensions such
92	// as non-standard reasoning/thinking fields.
93	type RequestOptions struct {
94		MaxTokens int
95		// Temperature/TopP/TopK/MinP/RepetitionPenalty are sampling controls.
96		// TopP is OpenAI-standard; TopK / MinP / RepetitionPenalty are
97		// non-standard OpenAI-compat extras that omlx, lmstudio, vLLM, and
98		// llama.cpp accept as top-level body fields. Nil means unset
99		// (server default applies). RepetitionPenalty > 1.0 prevents
100		// exact-token loops.
101		Temperature       *float64
102		TopP              *float64
103		TopK              *int
104		MinP              *float64
105		RepetitionPenalty *float64
106		Seed              int64
107		Stop              []string
108		ExtraOptions      []option.RequestOption
109		// CachePolicy mirrors agent.Options.CachePolicy. The OpenAI-compatible
110		// protocol layer does not act on it today; it is plumbed so a future
111		// caching-aware OpenAI-style provider has a typed field to consume.
112		CachePolicy string
113	}
114	
115	// ChatResult is a protocol-level non-streaming response without provider
116	// identity metadata.
117	type ChatResult struct {
118		Model        string
119		Content      string
120		FinishReason string
121		ToolCalls    []agent.ToolCall
122		Usage        agent.TokenUsage
123		RawUsage     string
124	}
125	
126	// CostHook extracts provider-owned cost data from a raw usage object. The SDK
127	// only calls the hook; it does not know provider-specific attribution rules.
128	type CostHook func(rawUsage string) *agent.CostAttribution
129	
130	// StreamAttemptHook builds provider-owned final attempt metadata for a stream.
131	type StreamAttemptHook func(responseModel string, cost *agent.CostAttribution) *agent.AttemptMetadata
132	
133	// StreamHooks are optional provider callbacks used by streaming conversion.
134	type StreamHooks struct {
135		Cost    CostHook
136		Attempt StreamAttemptHook
137	}
138	
139	// Chat executes one non-streaming Chat Completions request.
140	func (c *Client) Chat(ctx context.Context, model string, messages []agent.Message, tools []agent.ToolDef, opts RequestOptions) (ChatResult, error) {
141		params := buildParams(model, messages, tools, opts)
142		completion, err := c.client.Chat.Completions.New(ctx, params, opts.ExtraOptions...)
143		if err != nil {
144			return ChatResult{}, err
145		}
146	
147		result := ChatResult{
148			Model:    completion.Model,
149			RawUsage: completion.Usage.RawJSON(),
150		}
151		if completion.Usage.TotalTokens != 0 {
152			result.Usage = tokenUsage(
153				int(completion.Usage.PromptTokens),
154				int(completion.Usage.CompletionTokens),
155				int(completion.Usage.TotalTokens),
156				int(completion.Usage.PromptTokensDetails.CachedTokens),
157			)
158			result.Usage.Reasoning = extractReasoningTokens(result.RawUsage)
159		}
160	
161		if len(completion.Choices) > 0 {
162			choice := completion.Choices[0]
163			result.Content = choice.Message.Content
164			result.FinishReason = string(choice.FinishReason)
165			result.ToolCalls = extractToolCalls(choice.Message.ToolCalls)
166		}
167	
168		return result, nil
169	}
