171	// ChatStream executes one streaming Chat Completions request and converts
172	// chunks into agent stream deltas.
173	func (c *Client) ChatStream(ctx context.Context, model string, messages []agent.Message, tools []agent.ToolDef, opts RequestOptions, hooks StreamHooks) (<-chan agent.StreamDelta, error) {
174		params := buildParams(model, messages, tools, opts)
175		params.StreamOptions = oai.ChatCompletionStreamOptionsParam{
176			IncludeUsage: oai.Bool(true),
177		}
178	
179		stream := c.client.Chat.Completions.NewStreaming(ctx, params, opts.ExtraOptions...)
180	
181		ch := make(chan agent.StreamDelta, 1)
182		go func() {
183			defer close(ch)
184			send := func(delta agent.StreamDelta) {
185				delta.ArrivedAt = time.Now()
186				ch <- delta
187			}
188	
189			// OpenAI only sends tool call ID in the first chunk for each index;
190			// subsequent argument chunks carry the index but have an empty ID.
191			indexToID := make(map[int]string)
192			responseModel := model
193			var streamCost *agent.CostAttribution
194			for stream.Next() {
195				chunk := stream.Current()
196				if chunk.Model != "" {
197					responseModel = chunk.Model
198				}
199				if hooks.Cost != nil {
200					if cost := hooks.Cost(chunk.Usage.RawJSON()); cost != nil {
201						streamCost = cost
202					}
203				}
204	
205				reasoningContent := extractReasoningContent(chunk.RawJSON())
206	
207				if len(chunk.Choices) > 0 {
208					choice := chunk.Choices[0]
209	
210					for _, tc := range choice.Delta.ToolCalls {
211						id := tc.ID
212						if id != "" {
213							indexToID[int(tc.Index)] = id
214						} else {
215							id = indexToID[int(tc.Index)]
216						}
217						send(agent.StreamDelta{
218							Model:        chunk.Model,
219							ToolCallID:   id,
220							ToolCallName: tc.Function.Name,
221							ToolCallArgs: tc.Function.Arguments,
222						})
223					}
224	
225					if choice.Delta.Content != "" || choice.FinishReason != "" || reasoningContent != "" {
226						send(agent.StreamDelta{
227							Model:            chunk.Model,
228							Content:          choice.Delta.Content,
229							ReasoningContent: reasoningContent,
230							FinishReason:     string(choice.FinishReason),
231						})
232					} else if len(choice.Delta.ToolCalls) == 0 {
233						send(agent.StreamDelta{
234							Model:        chunk.Model,
235							FinishReason: string(choice.FinishReason),
236						})
237					}
238				} else {
239					send(agent.StreamDelta{Model: chunk.Model})
240				}
241	
242				if chunk.Usage.TotalTokens != 0 {
243					usage := tokenUsage(
244						int(chunk.Usage.PromptTokens),
245						int(chunk.Usage.CompletionTokens),
246						int(chunk.Usage.TotalTokens),
247						int(chunk.Usage.PromptTokensDetails.CachedTokens),
248					)
249					usage.Reasoning = extractReasoningTokens(chunk.Usage.RawJSON())
250					send(agent.StreamDelta{Usage: &usage})
251				}
252			}
253	
254			if err := stream.Err(); err != nil {
255				send(agent.StreamDelta{Err: classifyStreamErr(err)})
256				return
257			}
258	
259			done := agent.StreamDelta{
260				Model: responseModel,
261				Done:  true,
262			}
263			if hooks.Attempt != nil {
264				done.Attempt = hooks.Attempt(responseModel, streamCost)
265			}
266			send(done)
267		}()
268	
269		return ch, nil
270	}
271	
272	func buildParams(model string, messages []agent.Message, tools []agent.ToolDef, opts RequestOptions) oai.ChatCompletionNewParams {
273		params := oai.ChatCompletionNewParams{
274			Model:    model,
275			Messages: convertMessages(messages),
276		}
277		if len(tools) > 0 {
278			params.Tools = convertTools(tools)
279		}
280		if opts.MaxTokens > 0 {
281			params.MaxTokens = oai.Int(int64(opts.MaxTokens))
282		}
283		if opts.Temperature != nil {
284			params.Temperature = oai.Float(*opts.Temperature)
285		}
286		if opts.TopP != nil {
287			params.TopP = oai.Float(*opts.TopP)
288		}
289		if opts.Seed != 0 {
290			params.Seed = oai.Int(opts.Seed)
291		}
292		if len(opts.Stop) > 0 {
293			params.Stop = oai.ChatCompletionNewParamsStopUnion{OfStringArray: opts.Stop}
294		}
295		return params
296	}
297	
298	func convertMessages(msgs []agent.Message) []oai.ChatCompletionMessageParamUnion {
299		var result []oai.ChatCompletionMessageParamUnion
300		for _, m := range msgs {
301			switch m.Role {
302			case agent.RoleSystem:
303				result = append(result, oai.SystemMessage(m.Content))
304			case agent.RoleUser:
305				result = append(result, oai.UserMessage(m.Content))
306			case agent.RoleAssistant:
307				if len(m.ToolCalls) > 0 {
308					var toolCalls []oai.ChatCompletionMessageToolCallParam
309					for _, tc := range m.ToolCalls {
310						toolCalls = append(toolCalls, oai.ChatCompletionMessageToolCallParam{
311							ID: tc.ID,
312							Function: oai.ChatCompletionMessageToolCallFunctionParam{
313								Name:      tc.Name,
314								Arguments: string(tc.Arguments),
315							},
316						})
317					}
318					assistant := oai.ChatCompletionAssistantMessageParam{
319						Content: oai.ChatCompletionAssistantMessageParamContentUnion{
320							OfString: param.NewOpt(m.Content),
321						},
322						ToolCalls: toolCalls,
323					}
324					result = append(result, oai.ChatCompletionMessageParamUnion{OfAssistant: &assistant})
325				} else {
326					result = append(result, oai.AssistantMessage(m.Content))
327				}
328			case agent.RoleTool:
329				result = append(result, oai.ToolMessage(m.Content, m.ToolCallID))
330			}
331		}
332		return result
333	}
334	
335	func convertTools(tools []agent.ToolDef) []oai.ChatCompletionToolParam {
336		var result []oai.ChatCompletionToolParam
337		for _, t := range tools {
338			var params map[string]interface{}
339			_ = json.Unmarshal(t.Parameters, &params)
340	
341			result = append(result, oai.ChatCompletionToolParam{
342				Function: oai.FunctionDefinitionParam{
343					Name:        t.Name,
344					Description: oai.String(t.Description),
345					Parameters:  oai.FunctionParameters(params),
346				},
347			})
348		}
349		return result
350	}
351	
352	func extractToolCalls(calls []oai.ChatCompletionMessageToolCall) []agent.ToolCall {
353		if len(calls) == 0 {
354			return nil
355		}
356		var result []agent.ToolCall
357		for _, c := range calls {
358			result = append(result, agent.ToolCall{
359				ID:        c.ID,
360				Name:      c.Function.Name,
361				Arguments: json.RawMessage(c.Function.Arguments),
362			})
363		}
364		return result
365	}
366	
367	func extractReasoningContent(rawJSON string) string {
368		if rawJSON == "" {
369			return ""
370		}
371		var raw struct {
372			Choices []struct {
373				Delta struct {
374					ReasoningContent string `json:"reasoning_content"`
375				} `json:"delta"`
376			} `json:"choices"`
377		}
378		if err := json.Unmarshal([]byte(rawJSON), &raw); err != nil || len(raw.Choices) == 0 {
379			return ""
380		}
381		return raw.Choices[0].Delta.ReasoningContent
382	}
383	
384	func tokenUsage(input, output, total, cacheRead int) agent.TokenUsage {
385		usage := agent.TokenUsage{
386			Input:  input,
387			Output: output,
388			Total:  total,
389		}
390		if cacheRead > 0 {
391			usage.CacheRead = cacheRead
392		}
393		return usage
394	}
395	
396	// extractReasoningTokens reads usage.completion_tokens_details.reasoning_tokens
397	// from the raw usage JSON. The OpenAI Go SDK doesn't expose this field
398	// directly through its typed Usage struct (it's in completion_tokens_details
399	// which the SDK exposes on some models but not others), so we parse it from
400	// the raw JSON. Returns 0 when absent. Servers that emit reasoning_tokens:
401	// OpenAI (o1/o3/gpt-5+ thinking models), DeepSeek R1, Qwen3 thinking-mode
402	// builds (vLLM, llama.cpp, oMLX), DwarfStar 4 (ds4-server).
403	func extractReasoningTokens(rawUsageJSON string) int {
404		if rawUsageJSON == "" {
405			return 0
406		}
407		var raw struct {
408			CompletionTokensDetails struct {
409				ReasoningTokens int `json:"reasoning_tokens"`
410			} `json:"completion_tokens_details"`
411			// Some non-OpenAI servers put reasoning_tokens at the top level.
412			ReasoningTokens *int `json:"reasoning_tokens,omitempty"`
413		}
414		if err := json.Unmarshal([]byte(rawUsageJSON), &raw); err != nil {
415			return 0
416		}
417		if raw.ReasoningTokens != nil && *raw.ReasoningTokens > 0 {
418			return *raw.ReasoningTokens
419		}
420		return raw.CompletionTokensDetails.ReasoningTokens
421	}
