// Command bench discovers (harness, provider, model) candidates from
// agent config and runs a corpus of small tasks to produce per-task metrics.
package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/easel/fizeau/internal/productinfo"
)

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	if len(args) == 0 {
		printUsage()
		return 2
	}

	switch args[0] {
	case "discover":
		return cmdDiscover(args[1:])
	case "run":
		return cmdRun(args[1:])
	case "report":
		return cmdReport(args[1:])
	case "profiles":
		return cmdProfiles(args[1:])
	case "fhi":
		return cmdFHI(args[1:])
	case "evidence":
		return cmdEvidence(args[1:])
	case "matrix":
		return cmdMatrix(args[1:])
	case "matrix-aggregate":
		return cmdMatrixAggregate(args[1:])
	case "matrix-index":
		return cmdMatrixIndex(args[1:])
	case "sweep":
		return cmdSweep(args[1:])
	case "help", "-h", "--help":
		printUsage()
		return 0
	default:
		fmt.Fprintf(os.Stderr, "%s: unknown command %q\n", benchCommandName(), args[0])
		printUsage()
		return 2
	}
}

func benchCommandName() string {
	return productinfo.BinaryName + "-bench"
}

func printUsage() {
	fmt.Fprintf(os.Stderr, `Usage: %s <command> [flags]

Commands:
  discover   List discovered (harness, provider, model) candidates
  run        Run corpus against discovered candidates
  report     Render a results file as table, json, or markdown
  profiles   Manage v7 benchmark profiles (subcommand: list)
  fhi        Generate benchmark-specific deltas or cross-benchmark FHI claims
  evidence   Validate and append benchmark evidence records, including curated external imports
  matrix     Run the SD-010 harness/profile/task matrix
  matrix-aggregate
             Aggregate matrix cell reports into matrix.json, matrix.md, costs.json
  matrix-index
             Consolidate report.json files into phase-independent indexes
  sweep      Run the TB-2.1 staged sweep with phase and resource-group scheduling

Run '%s <command> -h' for command-specific flags.
`, benchCommandName(), benchCommandName())
}

// resolveWorkDir returns the working directory: --work-dir flag or cwd.
func resolveWorkDir(wd string) string {
	if wd != "" {
		return wd
	}
	d, err := os.Getwd()
	if err != nil {
		return "."
	}
	return d
}

// flagSet creates a FlagSet that writes to stderr with ContinueOnError.
func flagSet(name string) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	return fs
}

// Command docgen-cli regenerates the Hugo CLI reference under
// website/content/docs/cli/ by walking the fiz Cobra command tree.
//
// Output:
//   - website/content/docs/cli/_index.md          (root command page)
//   - website/content/docs/cli/<dotted>.md        (per-subcommand pages)
//
// Run via `make docs-cli`. The generator is deterministic: re-running it
// without source changes produces byte-identical files.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/easel/fizeau/agentcli"
	"github.com/spf13/cobra"
	"github.com/spf13/cobra/doc"
)

func main() {
	out := flag.String("out", "website/content/docs/cli", "output directory for generated CLI docs")
	flag.Parse()

	root := agentcli.MountCLI()
	disableAutoGenTag(root)

	if err := os.MkdirAll(*out, 0o750); err != nil {
		fail(err)
	}
	if err := cleanGenerated(*out); err != nil {
		fail(err)
	}

	// Section landing page (Hextra reads _index.md as the section root).
	if err := writeIndex(*out, root); err != nil {
		fail(err)
	}

	// Per-command pages. We avoid cobra/doc.GenMarkdownTree because we want
	// custom front-matter and rewritten cross-links, but we still use
	// GenMarkdownCustom to render the body — keeping us aligned with cobra's
	// canonical formatting.
	pages := collectCommands(root)
	for _, c := range pages {
		if c == root {
			continue
		}
		if err := writeCommand(*out, root, c); err != nil {
			fail(err)
		}
	}
}

// disableAutoGenTag turns off cobra's "Auto generated by spf13/cobra on
// <date>" footer recursively. Without this the output churns daily, breaking
// idempotency.
func disableAutoGenTag(c *cobra.Command) {
	c.DisableAutoGenTag = true
	for _, child := range c.Commands() {
		disableAutoGenTag(child)
	}
}

// collectCommands returns root + every available descendant in deterministic
// (sorted) order.
func collectCommands(root *cobra.Command) []*cobra.Command {
	var out []*cobra.Command
	var walk func(c *cobra.Command)
	walk = func(c *cobra.Command) {
		out = append(out, c)
		children := append([]*cobra.Command(nil), c.Commands()...)
		sort.Slice(children, func(i, j int) bool { return children[i].Name() < children[j].Name() })
		for _, child := range children {
			if !child.IsAvailableCommand() || child.IsAdditionalHelpTopicCommand() {
				continue
			}
			walk(child)
		}
	}
	walk(root)
	return out
}

// slug converts "fiz catalog show" -> "fiz_catalog_show".
func slug(cmd *cobra.Command) string {
	return strings.ReplaceAll(cmd.CommandPath(), " ", "_")
}

