12	// Reasoning is the canonical scalar for model-side reasoning controls.
13	type Reasoning string
14	
15	const (
16		ReasoningAuto    Reasoning = "auto"
17		ReasoningOff     Reasoning = "off"
18		ReasoningLow     Reasoning = "low"
19		ReasoningMedium  Reasoning = "medium"
20		ReasoningHigh    Reasoning = "high"
21		ReasoningMinimal Reasoning = "minimal"
22		ReasoningXHigh   Reasoning = "xhigh"
23		ReasoningMax     Reasoning = "max"
24	)
25	
26	// PortableBudgets are fallback named reasoning token budgets.
27	var PortableBudgets = map[Reasoning]int{
28		ReasoningOff:    0,
29		ReasoningLow:    2048,
30		ReasoningMedium: 8192,
31		ReasoningHigh:   32768,
32	}
33	
34	// ReasoningTokens returns a numeric reasoning-token request.
35	func ReasoningTokens(n int) Reasoning {
36		return Reasoning(strconv.Itoa(n))
37	}
38	
39	type Kind string
40	
41	const (
42		KindUnset  Kind = "unset"
43		KindAuto   Kind = "auto"
44		KindOff    Kind = "off"
45		KindNamed  Kind = "named"
46		KindTokens Kind = "tokens"
47	)
48	
49	type Policy struct {
50		Kind   Kind
51		Value  Reasoning
52		Tokens int
53	}
54	
55	func (p Policy) IsSet() bool {
56		return p.Kind != KindUnset
57	}
58	
59	func (p Policy) IsExplicitOff() bool {
60		return p.Kind == KindOff || (p.Kind == KindTokens && p.Tokens == 0)
61	}
62	
63	func Normalize(value string) (Reasoning, error) {
64		p, err := ParseString(value)
65		if err != nil {
66			return "", err
67		}
68		return p.Value, nil
69	}
70	
71	func ParseString(value string) (Policy, error) {
72		s := strings.ToLower(strings.TrimSpace(value))
73		if s == "" {
