107	func Parse(value any) (Policy, error) {
108		switch v := value.(type) {
109		case nil:
110			return Policy{Kind: KindUnset}, nil
111		case Reasoning:
112			return ParseString(string(v))
113		case string:
114			return ParseString(v)
115		case int:
116			return ParseString(strconv.Itoa(v))
117		case int64:
118			return ParseString(strconv.FormatInt(v, 10))
119		case float64:
120			if v != float64(int(v)) {
121				return Policy{}, fmt.Errorf("reasoning: numeric value %v must be an integer", v)
122			}
123			return ParseString(strconv.Itoa(int(v)))
124		case json.Number:
125			i, err := strconv.Atoi(v.String())
126			if err != nil {
127				return Policy{}, fmt.Errorf("reasoning: numeric value %q must be an integer", v.String())
128			}
129			return ParseString(strconv.Itoa(i))
130		default:
131			return Policy{}, fmt.Errorf("reasoning: unsupported scalar type %T", value)
132		}
133	}
