25		// QuotaHeaderParser, when set, is called on every response to convert
26		// the response Header into a quotaheaders.Signal. The signal is then
27		// forwarded to QuotaSignalObserver. Different providers (OpenAI vs
28		// OpenRouter) use different parsers, so the protocol layer takes the
29		// parser as a function and stays provider-agnostic.
30		QuotaHeaderParser func(http.Header, time.Time) quotaheaders.Signal
31		// QuotaSignalObserver, when set together with QuotaHeaderParser, receives
32		// the parsed signal on every response. The service layer wires this to
33		// the provider quota state machine.
34		QuotaSignalObserver func(quotaheaders.Signal)
35	}
