42	// NewClient creates an OpenAI-compatible protocol client.
43	func NewClient(cfg Config) *Client {
44		opts := []option.RequestOption{
45			option.WithBaseURL(cfg.BaseURL),
46			option.WithMaxRetries(0),
47		}
48		if cfg.APIKey != "" {
49			opts = append(opts, option.WithAPIKey(cfg.APIKey))
50		} else {
51			opts = append(opts, option.WithAPIKey("not-needed"))
52		}
53		for k, v := range cfg.Headers {
54			opts = append(opts, option.WithHeader(k, v))
55		}
56		// SSE comment-frame filter must sit before the debug sink so the sink
57		// observes the same byte stream the decoder will see. Middlewares are
58		// applied in registration order, outermost first.
59		opts = append(opts, option.WithMiddleware(SSEFilterMiddleware()))
60		if s := ResolveDebugSink(); s != nil {
61			opts = append(opts, option.WithMiddleware(DebugMiddleware(s)))
62		}
63		if cfg.QuotaHeaderParser != nil && cfg.QuotaSignalObserver != nil {
64			opts = append(opts, option.WithMiddleware(quotaHeaderMiddleware(cfg.QuotaHeaderParser, cfg.QuotaSignalObserver)))
65		}
66	
67		client := oai.NewClient(opts...)
68		return &Client{client: &client}
69	}
