71	// quotaHeaderMiddleware returns a middleware that runs `parser` on every
72	// response Header and forwards the resulting Signal to `observer`. The
73	// middleware is a no-op when the upstream call returns an error before a
74	// Response is produced, and runs *after* the response has been received but
75	// *before* the SDK consumes its body — both branches still surface the same
76	// (resp, err) tuple to the caller.
77	func quotaHeaderMiddleware(parser func(http.Header, time.Time) quotaheaders.Signal, observer func(quotaheaders.Signal)) option.Middleware {
78		return func(req *http.Request, next option.MiddlewareNext) (*http.Response, error) {
79			resp, err := next(req)
80			if resp != nil {
81				signal := parser(resp.Header, time.Now())
82				if signal.Present {
83					observer(signal)
84				}
85			}
86			return resp, err
87		}
88	}
