1	package reasoning
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"strconv"
7		"strings"
8	
9		"gopkg.in/yaml.v3"
10	)
11	
12	// Reasoning is the canonical scalar for model-side reasoning controls.
13	type Reasoning string
14	
15	const (
16		ReasoningAuto    Reasoning = "auto"
17		ReasoningOff     Reasoning = "off"
18		ReasoningLow     Reasoning = "low"
19		ReasoningMedium  Reasoning = "medium"
20		ReasoningHigh    Reasoning = "high"
21		ReasoningMinimal Reasoning = "minimal"
22		ReasoningXHigh   Reasoning = "xhigh"
23		ReasoningMax     Reasoning = "max"
24	)
25	
26	// PortableBudgets are fallback named reasoning token budgets.
27	var PortableBudgets = map[Reasoning]int{
28		ReasoningOff:    0,
29		ReasoningLow:    2048,
30		ReasoningMedium: 8192,
31		ReasoningHigh:   32768,
32	}
33	
34	// ReasoningTokens returns a numeric reasoning-token request.
35	func ReasoningTokens(n int) Reasoning {
36		return Reasoning(strconv.Itoa(n))
37	}
38	
39	type Kind string
40	
41	const (
42		KindUnset  Kind = "unset"
43		KindAuto   Kind = "auto"
44		KindOff    Kind = "off"
45		KindNamed  Kind = "named"
46		KindTokens Kind = "tokens"
47	)
48	
49	type Policy struct {
50		Kind   Kind
51		Value  Reasoning
52		Tokens int
53	}
54	
55	func (p Policy) IsSet() bool {
56		return p.Kind != KindUnset
57	}
58	
59	func (p Policy) IsExplicitOff() bool {
60		return p.Kind == KindOff || (p.Kind == KindTokens && p.Tokens == 0)
61	}
62	
63	func Normalize(value string) (Reasoning, error) {
64		p, err := ParseString(value)
65		if err != nil {
66			return "", err
67		}
68		return p.Value, nil
69	}
70	
71	func ParseString(value string) (Policy, error) {
72		s := strings.ToLower(strings.TrimSpace(value))
73		if s == "" {
74			return Policy{Kind: KindUnset}, nil
75		}
76		switch s {
77		case "auto":
78			return Policy{Kind: KindAuto, Value: ReasoningAuto}, nil
79		case "off", "none", "false":
80			return Policy{Kind: KindOff, Value: ReasoningOff}, nil
81		case "low":
82			return Policy{Kind: KindNamed, Value: ReasoningLow}, nil
83		case "medium":
84			return Policy{Kind: KindNamed, Value: ReasoningMedium}, nil
85		case "high":
86			return Policy{Kind: KindNamed, Value: ReasoningHigh}, nil
87		case "minimal":
88			return Policy{Kind: KindNamed, Value: ReasoningMinimal}, nil
89		case "x-high", "x_high", "xhigh":
90			return Policy{Kind: KindNamed, Value: ReasoningXHigh}, nil
91		case "max":
92			return Policy{Kind: KindNamed, Value: ReasoningMax}, nil
93		}
94		tokens, err := strconv.Atoi(s)
95		if err == nil {
96			if tokens < 0 {
97				return Policy{}, fmt.Errorf("reasoning: negative token budget %d is invalid", tokens)
98			}
99			if tokens == 0 {
100				return Policy{Kind: KindOff, Value: ReasoningOff, Tokens: 0}, nil
101			}
102			return Policy{Kind: KindTokens, Value: ReasoningTokens(tokens), Tokens: tokens}, nil
103		}
104		return Policy{}, fmt.Errorf("reasoning: unsupported value %q", value)
105	}
106	
107	func Parse(value any) (Policy, error) {
108		switch v := value.(type) {
109		case nil:
110			return Policy{Kind: KindUnset}, nil
111		case Reasoning:
112			return ParseString(string(v))
113		case string:
114			return ParseString(v)
115		case int:
116			return ParseString(strconv.Itoa(v))
117		case int64:
118			return ParseString(strconv.FormatInt(v, 10))
119		case float64:
120			if v != float64(int(v)) {
121				return Policy{}, fmt.Errorf("reasoning: numeric value %v must be an integer", v)
122			}
123			return ParseString(strconv.Itoa(int(v)))
124		case json.Number:
125			i, err := strconv.Atoi(v.String())
126			if err != nil {
127				return Policy{}, fmt.Errorf("reasoning: numeric value %q must be an integer", v.String())
128			}
129			return ParseString(strconv.Itoa(i))
130		default:
131			return Policy{}, fmt.Errorf("reasoning: unsupported scalar type %T", value)
132		}
133	}
134	
135	func BudgetFor(policy Policy, budgets map[Reasoning]int, maxTokens int) (int, error) {
136		switch policy.Kind {
137		case KindUnset, KindAuto:
138			return 0, nil
139		case KindOff:
140			return 0, nil
141		case KindTokens:
142			if maxTokens > 0 && policy.Tokens > maxTokens {
143				return 0, fmt.Errorf("reasoning: token budget %d exceeds maximum %d", policy.Tokens, maxTokens)
144			}
145			return policy.Tokens, nil
146		case KindNamed:
147			if policy.Value == ReasoningMax {
148				if maxTokens <= 0 {
149					return 0, fmt.Errorf("reasoning: max requires a known model/provider maximum")
150				}
151				return maxTokens, nil
152			}
153			if budgets != nil {
154				if budget, ok := budgets[policy.Value]; ok {
155					return budget, nil
156				}
157			}
158			if budget, ok := PortableBudgets[policy.Value]; ok {
159				if maxTokens > 0 && budget > maxTokens {
160					return 0, fmt.Errorf("reasoning: %s budget %d exceeds maximum %d", policy.Value, budget, maxTokens)
161				}
162				return budget, nil
163			}
164			return 0, fmt.Errorf("reasoning: unsupported named value %q for numeric budget", policy.Value)
165		default:
166			return 0, fmt.Errorf("reasoning: unsupported policy kind %q", policy.Kind)
167		}
168	}
169	
170	func (r *Reasoning) UnmarshalJSON(data []byte) error {
171		var s string
172		if err := json.Unmarshal(data, &s); err == nil {
173			normalized, err := Normalize(s)
174			if err != nil {
175				return err
176			}
177			*r = normalized
178			return nil
179		}
180		var n json.Number
181		if err := json.Unmarshal(data, &n); err == nil {
182			policy, err := Parse(n)
183			if err != nil {
184				return err
185			}
186			*r = policy.Value
187			return nil
188		}
189		return fmt.Errorf("reasoning: JSON value must be a string or integer")
190	}
191	
192	func (r *Reasoning) UnmarshalYAML(value *yaml.Node) error {
193		switch value.Kind {
194		case yaml.ScalarNode:
195			policy, err := ParseString(value.Value)
196			if err != nil {
197				return err
198			}
199			*r = policy.Value
200			return nil
201		default:
202			return fmt.Errorf("reasoning: YAML value must be a scalar")
203		}
204	}
205

150	// caches both the full list and the selected model.
151	// Subsequent calls return the cached value without hitting the network.
152	func (p *Provider) resolveModel(ctx context.Context) (string, error) {
153		if p.model != "" {
154			return p.model, nil
155		}
156		p.discoverOnce.Do(func() {
157			candidates, err := DiscoverModels(ctx, p.baseURL, p.apiKey)
158			if err != nil {
159				p.discoverErr = err
160				return
161			}
162			ranked, err := RankModels(candidates, p.knownModels, p.modelPattern)
163			if err != nil {
164				p.discoverErr = err
165				return
166			}
167			p.discoveredModels = ranked
168			selected := SelectModel(ranked)
169			if selected == "" {
170				p.discoverErr = fmt.Errorf("openai: no models returned by %s/models", p.baseURL)
171				return
172			}
173			p.model = selected
174		})
175		return p.model, p.discoverErr
176	}
177	
178	func (p *Provider) Chat(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (agent.Response, error) {
179		model, err := p.resolveModel(ctx)
180		if err != nil {
181			return agent.Response{}, err
182		}
183		if opts.Model != "" {
184			model = opts.Model
185		}
186	
187		reqOpts, err := p.compatRequestOptions(model, opts)
188		if err != nil {
189			return agent.Response{}, err
190		}
191	
192		result, err := p.client.Chat(ctx, model, messages, tools, reqOpts)
193		if err != nil {
194			return agent.Response{}, fmt.Errorf("openai: %w", err)
195		}
196	
197		resp := agent.Response{
198			Model:        result.Model,
199			Content:      result.Content,
200			FinishReason: result.FinishReason,
201			ToolCalls:    result.ToolCalls,
202			Usage:        result.Usage,
203		}
204		resp.Attempt = p.attemptMetadata(model, result.Model, &agent.CostAttribution{
205			Source: agent.CostSourceUnknown,
206		})
207		if cost := p.costAttribution(result.RawUsage); cost != nil {
208			resp.Attempt.Cost = cost
209		}
210		return resp, nil
211	}
212	
213	// SessionStartMetadata reports the broad provider identity and configured model
214	// that should be recorded on session.start events.
215	func (p *Provider) SessionStartMetadata() (string, string) {
216		return p.providerName, p.model
217	}
218	
219	// ChatStartMetadata reports the resolved provider system and upstream server
220	// identity known when the provider is constructed.
221	func (p *Provider) ChatStartMetadata() (string, string, int) {
222		return p.providerSystem, p.serverAddress, p.serverPort
223	}
224	
225	// ChatStream implements agent.StreamingProvider for token-level streaming.
226	func (p *Provider) ChatStream(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (<-chan agent.StreamDelta, error) {
227		model, err := p.resolveModel(ctx)
228		if err != nil {
229			return nil, err
230		}
231		if opts.Model != "" {
232			model = opts.Model
233		}
234	
235		reqOpts, err := p.compatRequestOptions(model, opts)
236		if err != nil {
237			return nil, err
238		}
239	
240		return p.client.ChatStream(ctx, model, messages, tools, reqOpts, openaicompat.StreamHooks{
241			Cost: p.costAttribution,
242			Attempt: func(responseModel string, cost *agent.CostAttribution) *agent.AttemptMetadata {
243				return p.attemptMetadata(model, responseModel, streamAttemptCost(cost))
244			},
245		})
246	}
247	
248	// compatRequestOptions is the canonical openai-compat wire-field assembler
249	// and, per ADR-007 §3, the architectural home for any future
250	// (model_family × reasoning_state × profile) sampling-composition rule.
251	// Reasoning policy and the resolved sampling profile both reach this seam;
252	// when a profile field needs to be clipped or substituted because the
253	// model is in a thinking state (or vice-versa), the rule lives here — not
254	// in the resolver, not in the catalog.
255	//
256	// v1 ships without an active composition rule. The seeded "code" profile
257	// (T=0.6, top_p=0.95, top_k=20) matches Qwen3.x's published thinking-mode
258	// precise-coding recommendation exactly, and is also non-greedy enough to
259	// be safe in the non-thinking-mode case. When a future profile adds a
260	// value that diverges between thinking and non-thinking states for some
261	// family, add the clip rule here; for now, all five sampler fields pass
262	// through unchanged regardless of reasoning state.
263	func (p *Provider) compatRequestOptions(model string, opts agent.Options) (openaicompat.RequestOptions, error) {
264		extra, err := p.reasoningRequestOptions(model, opts)
265		if err != nil {
266			return openaicompat.RequestOptions{}, err
267		}
268		temperature := opts.Temperature
269		topP := opts.TopP
270		if nativeOpenAIUsesDefaultSamplingOnly(p.providerSystem, model) {
271			temperature = nil
272			topP = nil
273		}
274		// Non-standard sampling fields (top_k, min_p, repetition_penalty) ride
275		// as top-level body extras on OpenAI-compatible local/provider wires.
276		// OpenAI proper rejects these as unknown parameters, so only send them
277		// to compatibility providers that are known to accept them.
278		if p.providerSystem != "openai" {
279			if opts.TopK != nil {
280				extra = append(extra, option.WithJSONSet("top_k", *opts.TopK))
281			}
282			if opts.MinP != nil {
283				extra = append(extra, option.WithJSONSet("min_p", *opts.MinP))
284			}
285			if opts.RepetitionPenalty != nil {
286				extra = append(extra, option.WithJSONSet("repetition_penalty", *opts.RepetitionPenalty))
287			}
288		}
289		return openaicompat.RequestOptions{
290			MaxTokens:         opts.MaxTokens,
291			Temperature:       temperature,
292			TopP:              topP,
293			TopK:              opts.TopK,
294			MinP:              opts.MinP,
295			RepetitionPenalty: opts.RepetitionPenalty,
296			Seed:              opts.Seed,
297			Stop:              opts.Stop,
298			ExtraOptions:      extra,
299			CachePolicy:       opts.CachePolicy,
300		}, nil
301	}
302	
303	func nativeOpenAIUsesDefaultSamplingOnly(providerSystem, model string) bool {
304		if providerSystem != "openai" {
305			return false
306		}
307		return strings.HasPrefix(strings.ToLower(model), "gpt-5")
308	}
309	
310	func (p *Provider) attemptMetadata(requestedModel, responseModel string, cost *agent.CostAttribution) *agent.AttemptMetadata {
311		if cost == nil {
312			cost = &agent.CostAttribution{Source: agent.CostSourceUnknown}
313		}
314		return &agent.AttemptMetadata{
315			ProviderName:   p.providerName,
316			ProviderSystem: p.providerSystem,
317			ServerAddress:  p.serverAddress,
318			ServerPort:     p.serverPort,
319			RequestedModel: requestedModel,
320			ResponseModel:  responseModel,
321			ResolvedModel:  responseModel,
322			Cost:           cost,
323		}
324	}
325	
326	func (p *Provider) costAttribution(rawUsage string) *agent.CostAttribution {
327		if p.usageCost == nil {
328			return nil
329		}
330		cost, _ := p.usageCost(rawUsage)
331		return cost
332	}
333	
334	// reasoningRequestOptions builds per-request options. For thinking models
335	// (Qwen3, DeepSeek-R1 etc.) apply provider-specific non-standard body fields
336	// only when the concrete provider declares the matching wire support.
337	func (p *Provider) reasoningRequestOptions(model string, opts agent.Options) ([]option.RequestOption, error) {
338		policy, err := reasoningpolicy.Parse(opts.Reasoning)
339		if err != nil {
340			return nil, err
341		}
342		explicitRequest := policy.IsSet()
343		if !explicitRequest {
344			policy, err = reasoningpolicy.Parse(p.reasoningDefault)
345			if err != nil {
346				return nil, err
347			}
348		}
349

349	
350		if !policy.IsSet() || policy.Kind == reasoningpolicy.KindAuto {
351			return nil, nil
352		}
353	
354		// Catalog reasoning_wire metadata gates the wire shape before any
355		// provider-specific encoding runs. Models flagged as reasoning_wire=none
356		// have no reasoning surface at all; an explicit non-off request is a
357		// catalog/wire mismatch and must surface as an error rather than be
358		// silently dropped. Models flagged as reasoning_wire=model_id encode the
359		// reasoning level in the model name (e.g. fixed-variant Qwen3.6) and the
360		// upstream endpoint cannot honor an external reasoning toggle, so the
361		// reasoning field must be stripped from the wire body.
362		switch p.modelReasoningWireFor(model) {
363		case "none":
364			if explicitRequest && !policy.IsExplicitOff() {
365				return nil, fmt.Errorf("openai: model %q has reasoning_wire=none; explicit reasoning=%q is not supported", model, policy.Value)
366			}
367			return nil, nil
368		case "model_id":
369			return nil, nil
370		}
371	
372		if !p.SupportsThinking() {
373			if policy.IsExplicitOff() {
374				return nil, nil
375			}
376			if explicitRequest {
377				return nil, fmt.Errorf("openai: reasoning=%q is not supported by provider type %q", policy.Value, p.providerSystem)
378			}
379			return nil, nil
380		}
381	
382		if policy.IsExplicitOff() {
383			switch p.thinkingWireFormat() {
384			case ThinkingWireFormatQwen:
385				if !isQwenModel(model) {
386					if explicitRequest && p.strictThinkingModelMatch() {
387						return nil, fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
388					}
389					return nil, nil
390				}
391				return []option.RequestOption{
392					option.WithJSONSet("enable_thinking", false),
393					option.WithJSONSet("thinking_budget", 0),
394				}, nil
395			case ThinkingWireFormatOpenRouter:
396				return []option.RequestOption{option.WithJSONSet("reasoning", map[string]interface{}{
397					"effort": "none",
398				})}, nil
399			}
400			return nil, nil
401		}
402	
403		if p.thinkingWireFormat() == ThinkingWireFormatOpenRouter {
404			return openRouterReasoningOptions(policy)
405		}
406		if p.thinkingWireFormat() == ThinkingWireFormatQwen && !isQwenModel(model) {
407			if explicitRequest && p.strictThinkingModelMatch() {
408				return nil, fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
409			}
410			return nil, nil
411		}
412	
413		thinkingBudget, err := reasoningpolicy.BudgetFor(policy, nil, 0)
414		if err != nil {
415			return nil, fmt.Errorf("openai: %w", err)
416		}
417		if thinkingBudget <= 0 {
418			return nil, nil
419		}
420	
421		switch p.thinkingWireFormat() {
422		case ThinkingWireFormatQwen:
423			return []option.RequestOption{
424				option.WithJSONSet("enable_thinking", true),
425				option.WithJSONSet("thinking_budget", thinkingBudget),
426			}, nil
427		case "", ThinkingWireFormatThinkingMap:
428			return []option.RequestOption{option.WithJSONSet("thinking", map[string]interface{}{
429				"type":          "enabled",
430				"budget_tokens": thinkingBudget,
431			})}, nil
432		default:
433			return nil, fmt.Errorf("openai: unsupported thinking wire format %q for provider type %q", p.thinkingWireFormat(), p.providerSystem)
434		}
435	}
436	
437	// modelReasoningWireFor returns the catalog reasoning_wire value for the
438	// given model, defaulting to "provider" when the model is not catalog-known.
439	// Returned values are normalized: only "model_id" and "none" trigger
440	// catalog-driven wire overrides; everything else falls through to the
441	// provider's protocol capability path.
442	func (p *Provider) modelReasoningWireFor(model string) string {
443		if p.modelReasoningWire == nil || model == "" {
444			return ""
445		}
446		return p.modelReasoningWire[model]
447	}
448	
449	func isQwenModel(model string) bool {
450		return strings.Contains(strings.ToLower(model), "qwen")
451	}
452	
453	func openRouterReasoningOptions(policy reasoningpolicy.Policy) ([]option.RequestOption, error) {
454		reasoning := map[string]interface{}{}
455		switch policy.Kind {
456		case reasoningpolicy.KindTokens:
457			reasoning["max_tokens"] = policy.Tokens
458		case reasoningpolicy.KindNamed:
459			effort := string(policy.Value)
460			if policy.Value == reasoningpolicy.ReasoningMax {
461				effort = string(reasoningpolicy.ReasoningXHigh)
462			}
463			switch effort {
464			case "minimal", "low", "medium", "high", "xhigh":
465				reasoning["effort"] = effort
466			default:
467				return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning effort %q", policy.Value)
468			}
469		default:
470			return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning policy %q", policy.Kind)
471		}
472		return []option.RequestOption{option.WithJSONSet("reasoning", reasoning)}, nil
473	}
474	
475	var _ agent.Provider = (*Provider)(nil)
476	var _ agent.StreamingProvider = (*Provider)(nil)
477	
478	func endpointMetadata(baseURL string) (serverAddress string, serverPort int) {
479		serverAddress = "api.openai.com"
480		serverPort = 443
481	
482		if baseURL == "" {
483			return serverAddress, serverPort
484		}
485	
486		parsed, err := url.Parse(baseURL)
487		if err != nil {
488			return serverAddress, serverPort
489		}
490	
491		host := parsed.Hostname()
492		if host != "" {
493			serverAddress = host
494		}
495	
496		if port := parsed.Port(); port != "" {
497			if parsedPort, err := strconv.Atoi(port); err == nil {
498				serverPort = parsedPort
499			}
500		} else if strings.EqualFold(parsed.Scheme, "http") {
501			serverPort = 80
502		}
503	
504		return serverAddress, serverPort
505	}
506	
507	func streamAttemptCost(cost *agent.CostAttribution) *agent.CostAttribution {
508		if cost != nil {
509			return cost
510		}
511		return &agent.CostAttribution{Source: agent.CostSourceUnknown}
512	}
